<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import type {Session} from '../FleetAndDocuments/contracts';
import { useModuleRequests } from '../Office/useModuleRequests';
import {failure} from '../Administration/api';
const {all,request}=useModuleRequests();
import SearchSelect from '../Workshop/components/SearchSelect.vue';
import ReportTable from './ReportTable.vue';
import {names,states,labels,parseReport} from './contracts';
import type {Kind,Report,Row} from './contracts';
const props=defineProps<{session:Session|null}>();const emit=defineEmits<{denied:[error:unknown]}>();
const kind=ref<Kind>('transport'),from=ref(''),to=ref(''),status=ref(''),customer=ref(''),vehicle=ref(''),currency=ref(''),part=ref('');
const loading=ref(false),error=ref(''),lookupError=ref(''),report=ref<Report|null>(null),fields=ref<Record<string,string[]>>({});
const customers=ref<{value:string;label:string}[]>([]),vehicles=ref<{value:string;label:string}[]>([]),parts=ref<{value:string;label:string}[]>([]);
const allowed=computed(()=>props.session?.roles.includes('administrator')??false);let generation=0,sessionGeneration=0;
const clientFilter=computed(()=>['transport','billing'].includes(kind.value)),vehicleFilter=computed(()=>['transport','workshop'].includes(kind.value)),moneyFilter=computed(()=>['billing','expenses'].includes(kind.value)),partFilter=computed(()=>['stock','movements'].includes(kind.value));
const summaries=computed<{caption:string;rows:Row[]}[]>(()=>{
 if(!report.value)return [];
 const s=report.value.summary;
 if(Array.isArray(s))return [{caption:'Totales de todos los resultados filtrados',rows:s}];
 if('invoices'in s&&Array.isArray(s.invoices)&&'receipts'in s&&Array.isArray(s.receipts))return [{caption:'Facturas registradas en el período · importes y saldo actual',rows:s.invoices},{caption:'Cobros efectivamente registrados en el período',rows:s.receipts}];
 return [{caption:'Resumen actual',rows:[s as Row]}];
});
async function lookup():Promise<void>{const current=sessionGeneration;lookupError.value='';try{const [c,v,p]=await Promise.all([all<{id:string;name:string}>('/transport/lookups/customers'),all<{id:string;code:string}>('/transport/lookups/assets'),all<{id:string;code:string;description:string}>('/catalogs/spare-parts')]);if(current!==sessionGeneration)return;customers.value=c.map(x=>({value:x.id,label:x.name}));vehicles.value=v.map(x=>({value:x.id,label:x.code}));parts.value=p.map(x=>({value:x.id,label:`${x.code} · ${x.description}`}));}catch(e){if(current!==sessionGeneration)return;lookupError.value='No se pudieron cargar los selectores. Vuelve a consultar.';const problem=failure(e);if([401,403].includes(problem.status))emit('denied',problem);}}
async function consult(page=1):Promise<void>{if(!allowed.value)return;const current=++generation;loading.value=true;error.value='';fields.value={};report.value=null;try{const q=new URLSearchParams({page:String(page),per_page:'25'});const filters:Record<string,string>={};if(kind.value!=='stock'){filters.from=from.value;filters.to=to.value;filters.status=status.value;}if(clientFilter.value)filters.customer_id=customer.value;if(vehicleFilter.value)filters.fleet_asset_id=vehicle.value;if(moneyFilter.value)filters.currency=currency.value;if(partFilter.value)filters.spare_part_id=part.value;for(const[k,v]of Object.entries(filters))if(v)q.set(k,v);const result=parseReport(await request<unknown>(`/reports/${kind.value}?${q}`));if(current===generation)report.value=result;}catch(e){if(current!==generation)return;const p=failure(e);error.value=p.status===0?'No se pudo consultar el reporte. Comprueba la conexión y vuelve a consultar.':p.message;fields.value=p.fields;if([401,403].includes(p.status))emit('denied',p);}finally{if(current===generation)loading.value=false;}}
watch(kind,()=>{status.value='';report.value=null;generation++;loading.value=false;});
watch(()=>props.session?`${props.session.id}:${props.session.roles.join('|')}`:'',()=>{generation++;sessionGeneration++;report.value=null;customers.value=[];vehicles.value=[];parts.value=[];error.value='';loading.value=false;if(allowed.value){void lookup();}},{immediate:true});
onBeforeUnmount(()=>{generation++;sessionGeneration++;});
</script>
<template><section v-if="allowed" class="space-y-5"><p class="notice-info">Solo lectura. CRC y USD se muestran por separado, sin conversiones. Facturación no equivale a cobro; un gasto aprobado no implica pago o reembolso. Los estados son actuales.</p><form data-office-filter class="panel grid gap-4 sm:grid-cols-2 lg:grid-cols-3" @submit.prevent="consult()"><label>Reporte<select v-model="kind" aria-label="Reporte" class="field" :disabled="loading"><option v-for="(name,key) in names" :key="key" :value="key">{{name}}</option></select></label><template v-if="kind!=='stock'"><label>Desde<input v-model="from" type="date" class="field" :disabled="loading"></label><label>Hasta<input v-model="to" type="date" class="field" :min="from||undefined" :disabled="loading"></label><label>Estado o movimiento<select v-model="status" aria-label="Estado o movimiento" class="field" :disabled="loading"><option value="">Todos</option><option v-for="item in states[kind]" :key="item" :value="item">{{labels[item]??item}}</option></select></label></template><SearchSelect v-if="clientFilter" v-model="customer" :options="customers" label="Cliente" :disabled="loading"/><SearchSelect v-if="vehicleFilter" v-model="vehicle" :options="vehicles" label="Vehículo" :disabled="loading"/><SearchSelect v-if="partFilter" v-model="part" :options="parts" label="Repuesto" :disabled="loading"/><label v-if="moneyFilter">Moneda<select v-model="currency" aria-label="Moneda" class="field" :disabled="loading"><option value="">Todas · separadas</option><option>CRC</option><option>USD</option></select></label><div class="flex items-end"><button class="btn-primary" :disabled="loading">Consultar reporte</button></div></form><p v-if="lookupError" role="alert" class="notice-error">{{lookupError}} <button class="btn-secondary" :disabled="loading" @click="lookup">Recargar selectores</button></p><p v-if="loading" role="status">Consultando información persistida…</p><p v-if="error" role="alert" class="notice-error">{{error}}</p><ul v-if="Object.keys(fields).length" role="alert" class="notice-error"><li v-for="(messages,key) in fields" :key="key">{{key}}: {{messages.join(' ')}}</li></ul><template v-if="report"><p class="notice-info">{{report.note}}</p><ReportTable v-for="section in summaries" :key="section.caption" :rows="section.rows" :caption="section.caption"/><p class="font-semibold">{{report.meta.total}} registros · página {{report.meta.current_page}} de {{report.meta.last_page}}</p><ReportTable :rows="report.rows" :caption="names[report.kind]+' · registros originales'"/><div class="flex gap-3"><button class="btn-secondary" :disabled="loading||report.meta.current_page<=1" @click="consult(report.meta.current_page-1)">Anterior</button><button class="btn-secondary" :disabled="loading||report.meta.current_page>=report.meta.last_page" @click="consult(report.meta.current_page+1)">Siguiente</button></div><a :href="report.module_href" class="text-blue-800 underline">Abrir módulo original para consultar detalles</a><p class="text-sm">Conserva el identificador o código de la fila para localizar el registro en la vista original.</p></template></section></template>
